misal hari = "Sabtu"
misal nilai = 80

jika hari adalah "Sabtu" atau hari adalah "Minggu" {
  tulis("Hari ini libur.")
} lain {
  tulis("Hari ini sekolah.")
}

pilih hari {
  saat "Sabtu" / "Minggu" {
    tulis("Waktunya bermain.")
  }
  saat "Jumat" {
    tulis("Besok libur.")
  }
  lain {
    tulis("Jangan lupa PR.")
  }
}

jika nilai >= 75 dan hari bukan "Jumat" {
  tulis("Lulus!")
} lain {
  tulis("Belajar lagi, ya.")
}

pilih nilai {
  saat 100 tulis("Sempurna!")
  saat 80 / 90 tulis("Bagus sekali.")
  lain tulis("Terus berlatih.")
}

misal belanja = [
  { nama: "apel", harga: 3000 },
  { nama: "jeruk", harga: 2500 },
  { nama: "mangga", harga: 5000 }
]

misal total = 0
untuk setiap barang dalam belanja {
  tulis("{barang.nama}: {barang.harga}")
  total = total + barang.harga
}
tulis("Total: {total}")

misal uang = 10000
misal hari = 0
ulang {
  uang = uang + 1500
  hari = hari + 1
} sampai uang >= total
tulis("Cukup setelah {hari} hari menabung.")

fungsi jenjang(umur) {
  jika umur < 7 {
    hasilkan "TK"
  } lain jika umur <= 12 {
    hasilkan "SD"
  } lain {
    hasilkan "SMP atau lebih"
  }
}

misal nama = tanya("Siapa namamu?")
misal umur = tanya("Umurmu berapa?", Tipe.Angka)

jika umur kosong {
  tulis("Maaf, {nama}, itu bukan angka.")
} lain {
  tulis("{nama}, kamu cocok di {jenjang(umur)}.")
}

Hewan(nama) {
  .nama = nama

  suara() {
    hasilkan "..."
  }
}

Kucing(nama) turunan Hewan(nama) {
  suara() {
    hasilkan "meong"
  }
}

Anjing(nama) turunan Hewan(nama) {
  suara() {
    hasilkan "guk, bukan {..suara()}"
  }
}

misal kebun = [Kucing("Tom"), Anjing("Bobi"), Hewan("Kiki")]
untuk setiap hewan dalam kebun {
  jika hewan.nama bukan "Kiki" {
    tulis("{hewan.nama} bilang {hewan.suara()}")
  }
}
